mapper.select:
SELECT 1
FROM outgoing_personnel op
LEFT JOIN outgoing og ON og.out_id = op.out_id
LEFT JOIN u_user uu ON uu.user_id = op.user_id AND uu.status_cd = '0'
LEFT JOIN u_org_staff_rel uosl ON uosl.staff_id = uu.user_id AND uosl.status_cd = '0'
LEFT JOIN u_org uo ON uo.org_id = uosl.org_id AND uo.status_cd = '0'
LEFT JOIN t_dict td ON td.status_cd = uosl.rel_cd AND td.table_name = 'u_org_staff_rel' AND td.table_columns = 'rel_cd'
WHERE uu.`name` = #{name}
  AND uo.org_name = #{department}
  AND op.status_cd = '0' AND og.status_cd = '0' AND og.state = 3

      AND og.start_time <= #{fixedStartWorkDateTime}


      AND og.end_time >= #{fixedEndWorkDateTime}

LIMIT 1

SELECT b_id bId, personnel_id personnelId, user_id userId, out_id outId, operate
FROM business_outgoing_personnel
WHERE b_id = #{bId} AND operate = #{operate}

select t.personnel_id,t.personnel_id personnelId,t.create_time,t.create_time createTime,t.out_id,t.out_id
outId,t.status_cd,t.status_cd statusCd,t.b_id,t.b_id bId,t.user_id,t.user_id userId
from outgoing_personnel t
where 1 =1

    and t.personnel_id= #{personnelId}


    and t.create_time= #{createTime}


    and t.out_id= #{outId}


    and t.status_cd= #{statusCd}


    and t.b_id= #{bId}


    and t.user_id= #{userId}

order by t.create_time desc

    limit #{page}, #{row}

